// lib/model/task.dart
import 'package:objectbox/objectbox.dart';

@Entity()
class Task {
  @Id() // Annotate the id property
  int id = 0;

  String text;
  bool isCompleted;
  DateTime dateCreated;

  Task({
    required this.text,
    this.isCompleted = false,
  }) : dateCreated = DateTime.now();
}

